  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Faith, Trials and Love$j$, $j${"prompt": "The letters in this unit teach us to keep believing during trials and to show love in practical ways. Think about a trial a young person might face. Tell which teaching from Hebrews, James, Peter or John would help most and why. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Faith, Trials and Love$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$, $j${"questions": [{"q": "What is the main message of the book of Hebrews?", "options": ["Angels are greater than Jesus", "The temple will be rebuilt", "Believers must keep the old sacrifices", "Jesus is better than everything that came before"]}, {"q": "According to Hebrews 4:16, where may believers come boldly?", "options": ["To the mountain of Moses", "To the throne of grace", "To the temple in Jerusalem", "To the city gates"]}, {"q": "According to Hebrews 11:1, what is faith?", "options": ["A good feeling", "The substance of things hoped for, the evidence of things not seen", "A reward for good works", "A kind of luck"]}, {"q": "According to Hebrews 12:2, who are we to look unto?", "options": ["Jesus, the author and finisher of our faith", "The prophets", "The law", "The angels"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,0}'::int[], array[$j$Hebrews shows that Jesus is greater than the angels, Moses and the priests.$j$,$j$We may come boldly to the throne of grace to obtain mercy and find grace to help.$j$,$j$Hebrews 11:1 defines faith as the substance of things hoped for, the evidence of things not seen.$j$,$j$Hebrews 12:2 tells us to look unto Jesus the author and finisher of our faith.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Hebrews: Jesus Our Great High Priest and the Hall of Faith$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: James: Faith That Works$j$, $j${"questions": [{"q": "Who wrote the letter of James?", "options": ["James the son of Zebedee", "James, the brother of Jesus and a leader in Jerusalem", "Peter", "Paul"]}, {"q": "According to James 1:3, what does the trying of your faith work?", "options": ["Pride", "Wealth", "Fear", "Patience"]}, {"q": "What does James 1:22 tell believers to be?", "options": ["Teachers of the law", "Silent in the church", "Hearers only", "Doers of the word"]}, {"q": "According to James 2:26, what is faith without works?", "options": ["Dead", "Hidden", "Strong", "Complete"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: James: Faith That Works$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,0}'::int[], array[$j$The letter was written by James, the brother of Jesus and leader of the church in Jerusalem.$j$,$j$James 1:3 says the trying of your faith worketh patience.$j$,$j$James 1:22 says to be doers of the word and not hearers only.$j$,$j$James 2:26 says faith without works is dead also.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: James: Faith That Works$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: First and Second Peter: Hope in Suffering$j$, $j${"questions": [{"q": "To whom did Peter write his first letter?", "options": ["The priests in the temple", "Kings and rulers", "Believers scattered across Asia Minor who were suffering", "The church at Rome"]}, {"q": "According to 1 Peter 1:7, the trial of your faith is more precious than what?", "options": ["Land", "Fine linen", "Silver", "Gold that perisheth"]}, {"q": "What does 1 Peter 5:7 tell believers to cast upon the Lord?", "options": ["All their care", "Their nets", "Their crowns", "Their garments"]}, {"q": "What does 2 Peter 3:18 tell believers to do?", "options": ["Build a temple", "Grow in grace and in the knowledge of our Lord and Saviour Jesus Christ", "Return to the old law", "Stop gathering"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: First and Second Peter: Hope in Suffering$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,1}'::int[], array[$j$First Peter was written to scattered believers who suffered for their faith.$j$,$j$Peter said the trial of faith is much more precious than gold that perisheth.$j$,$j$Peter wrote, Casting all your care upon him; for he careth for you.$j$,$j$Peter ended his letter by urging believers to grow in grace and knowledge.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: First and Second Peter: Hope in Suffering$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: The Letters of John and Jude$j$, $j${"questions": [{"q": "According to 1 John 1:9, what will God do if we confess our sins?", "options": ["He will test us again", "He will ask us to pay", "He will forgive us and cleanse us from all unrighteousness", "He will ignore us"]}, {"q": "According to 1 John 4:8, what is God?", "options": ["Love", "King", "Judge", "Rock"]}, {"q": "Why does 1 John 4:19 say we love Him?", "options": ["Because we are strong", "Because He first loved us", "Because we are good", "Because we are wise"]}, {"q": "What did Jude urge believers to do in Jude 1:3?", "options": ["Keep silent", "Leave the church", "Earnestly contend for the faith which was once delivered unto the saints", "Rebuild the temple"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: The Letters of John and Jude$j$);
